                Show Loading Toast
            </Button>
            <Button
                onClick={() => {
                    toast.promise(
                        (async () => {
                            await new Promise((resolve) => setTimeout(resolve, 3000));
                        })(),
                        {
                            loading:
                                'Promise is loading... This text is longer to test animation of transition',
                            success: 'Promise resolved!',
                            error: 'Promise rejected.',
                        },
                    );
                }}
            >
                Show Promise Toast
            </Button>
            <Button
                onClick={() => {
                    toast('This is a toast with actions!', {
                        timeout: 20_000,
                        data: {
                            actions: [
                                {
                                    label: 'Retry',
                                    emphasis: 'primary',
                                    onClick: () => {
                                        alert('Retry clicked!');
                                    },
                                },
                                {
                                    label: 'Undo',
                                    emphasis: 'light',
                                    onClick: () => {
                                        alert('Undo clicked!');
                                    },
                                },
                            ],
                        },
                    });
                }}
            >
                Show Toast with Actions
            </Button>
            <Button
                onClick={() => {
                    toast({
                        title: 'Rich Toast',
                        description: 'This toast has both a title and a description.',
                        timeout: 20_000,
                    });
                }}
            >
                Show Rich Toast
            </Button>
            <Button
                onClick={() => {
                    toast({
                        id: 'unique-toast-id',
                        title: 'Unique Toast',
                        description:
                            "This toast has a unique ID. If you click the button multiple times, it won't create multiple toasts, but will update the existing one.",
                        timeout: 20_000,
                    });
                }}
            >
                Show Unique Toast
            </Button>
        </Box>
    );
};

